import yfinance as yf

# Test US stock tickers without suffix
tickers = ['MSFT', 'AAPL', 'NVDA', 'AMD', 'GOOGL', 'META']
for t in tickers:
    try:
        h = yf.Ticker(t).history(period='5d')
        if not h.empty:
            last = h.iloc[-1]
            print(f"{t}: Open={last['Open']}, High={last['High']}, Low={last['Low']}, Close={last['Close']}")
        else:
            print(f"{t}: No data")
    except Exception as e:
        print(f"{t}: Error - {e}")
EOF
